mapper.select:
SELECT m.member_no , m.id , m.name , m.birth , m.rank , m.team_id , t.name AS teamName FROM MEMBER m LEFT JOIN TEAM t ON m.team_id = t.id
AND m.member_no = #{memberNo}
AND m.id LIKE CONCAT('%', #{id}, '%')
AND m.name LIKE CONCAT('%', #{name}, '%')
AND m.birth LIKE CONCAT('%', #{birth}, '%')
AND m.rank = #{rank}
AND m.team_id = #{teamId}
AND t.name LIKE CONCAT('%', #{teamName}, '%')

mapper.update:
UPDATE MEMBER
   SET name = #{name}
     , birth = #{birth}
     , rank = #{rank}
     , team_id = #{teamId}
 WHERE member_no = #{memberNo}
